// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {LocalAdapter} from "./LocalAdapter.sol";
import {LocalQuote} from "../interfaces/ILocalAdapter.sol";

/// @title FeeAdapter
/// @author Agustin Aguilar
/// @notice Local adapter that pays exact quoted fees from a PDA inbox
contract FeeAdapter is LocalAdapter {
  address public immutable RECIPIENT;

  event FeePaid(address indexed _inbox, address indexed _recipient, address indexed _token, uint256 _amount);

  error ZeroAddress();
  error InvalidAmount();
  error UnsupportedRoute(address _tokenIn, address _tokenOut);

  constructor(address _recipient) {
    if (_recipient == address(0)) {
      revert ZeroAddress();
    }

    RECIPIENT = _recipient;
  }

  /// @notice Quotes an exact fee payment for an explicit non-zero input amount.
  /// @dev `_tokenOut` must match `_tokenIn`; fee operations produce no new asset.
  function quote(address _tokenIn, address _tokenOut, uint256 _amountIn, bytes calldata)
    external
    pure
    override
    returns (LocalQuote memory _quote)
  {
    if (_tokenIn != _tokenOut) {
      revert UnsupportedRoute(_tokenIn, _tokenOut);
    }
    if (_amountIn == 0) {
      revert InvalidAmount();
    }

    return LocalQuote({amountIn: _amountIn, amountOut: 0});
  }

  /// @notice Pays `_amountIn` of `_tokenIn` from `_inbox` to `RECIPIENT`.
  /// @dev `_tokenOut` must match `_tokenIn`; fee operations produce no new asset.
  function execute(address _inbox, address _tokenIn, address _tokenOut, uint256 _amountIn, bytes calldata)
    external
    override
    returns (uint256 _amountPaid)
  {
    if (_tokenIn != _tokenOut) {
      revert UnsupportedRoute(_tokenIn, _tokenOut);
    }
    if (_amountIn == 0) {
      revert InvalidAmount();
    }

    _payInboxAsset(_inbox, RECIPIENT, _tokenIn, _amountIn);

    emit FeePaid(_inbox, RECIPIENT, _tokenIn, _amountIn);
    return _amountIn;
  }
}

