/// @notice Callback used by trusted adapters to execute transactions from PDA inboxes
interface IInboxCallback {
  function executeLocalInboxTransaction(address _inbox, address _target, uint256 _value, bytes calldata _data)
    external
    returns (bytes memory _result);

  function executeBridgeInboxTransaction(address _inbox, address _target, uint256 _value, bytes calldata _data)
    external
    returns (bytes memory _result);
}

