pragma solidity ^0.8.26;

struct LocalQuote {
  /// @notice Amount of `_tokenIn` the operation would consume from the inbox
  uint256 amountIn;
  /// @notice Amount of `_tokenOut` the operation would produce for the route
  uint256 amountOut;
}

/// @title ILocalAdapter
/// @author Agustin Aguilar
/// @notice Interface for local route operations executed from an inbox
interface ILocalAdapter {
  /// @notice Quotes a local operation for an explicit non-zero input amount.
  /// @dev Intentionally non-view: stateful pool adapters may simulate swaps and unwind them with a revert.
  function quote(address _tokenIn, address _tokenOut, uint256 _amountIn, bytes calldata _adapterCalldata)
    external
    returns (LocalQuote memory _quote);

  /// @notice Executes a local operation from `_inbox`.
  function execute(
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    bytes calldata _adapterCalldata
  ) external returns (uint256 _amount);
}

